/** What a session's status dot says. */
enum class StatusRole {
    ACTIVE,
    IDLE,
    ATTENTION,
    FAILED,
    INACTIVE,
    ;

    companion object {
        fun of(status: String?): StatusRole = when (status) {
            "running", "queued", "preparing", "starting" -> ACTIVE
            "idle" -> IDLE
            "waiting", "interrupted", "cancelled" -> ATTENTION
            "failed", "error" -> FAILED
            "closed" -> INACTIVE
            else -> INACTIVE
        }
    }
}

