/** The working indicator: a glyph per tick, a verb every 25 ticks. */
object BriareusWorking {
    val glyphs = listOf("·", "✢", "✳", "✶", "✻", "✽", "✻", "✶", "✳", "✢")
    val verbs = listOf("Working", "Thinking", "Reasoning", "Tinkering", "Crafting", "Pondering")
    fun glyph(tick: Int): String = glyphs[tick.mod(glyphs.size)]
    fun verb(tick: Int): String = verbs[(tick / 25).mod(verbs.size)]
